// Aliases so slightly different phrasings of the same skill (as typed by a
// candidate, extracted from a resume, or written into job hardSkills
// strings) resolve to the same icon.
const ALIASES: Record<string, string> = {
  "nodedotjs": "nodejs",
  "node": "nodejs",
  "reactjs": "react",
  "postgres": "postgresql",
  "js": "javascript",
  "amazons3": "aws",
};

function normalizeSkillName(skill: string): string {
  return skill
    .toLowerCase()
    .replace(/\.js$/, "js")
    .replace(/[^a-z0-9]/g, "");
}

/** Returns the matching brand icon for a skill name, or null if none exists — callers should render a fallback (e.g. an initial-letter badge) in that case rather than treating it as an error. */
export function getSkillIcon(skill: string): SkillIconData | null {
  const key = normalizeSkillName(skill);
  if (SKILL_ICONS[key]) return SKILL_ICONS[key];
  const aliased = ALIASES[key];
  if (aliased && SKILL_ICONS[aliased]) return SKILL_ICONS[aliased];
  return null;
}
